export function requireAdmin(user: { role: string }) {
  if (user.role !== "admin") throw new Error("forbidden");
}

files.src/routes/delete-user.ts:
import { db } from "../db";
export async function deleteUser(req: { user: { role: string }; params: { id: string } }) {
  await db.users.delete(req.params.id);
}

files.src/routes/ban-user.ts:
import { db } from "../db";
export async function banUser(req: { user: { role: string }; params: { id: string } }) {
  await db.users.update(req.params.id, { banned: true });
}

